
export type TileValue = number | string;

export interface Tile {
  value: TileValue;
  isLocked: boolean;
}

export interface MathPuzzle {
  id: string;
  board: Tile[];
  swappedIndices: [number, number];
  correctSolution: TileValue[];
}

export interface MathLevel {
    level: number;
    description: string;
    hint: string;
    variations: PuzzleTemplate[];
}

interface PuzzleTemplate {
  // A mathematically correct equation. The puzzle is generated by swapping two elements.
  correct: string;
  // The two values (as strings) that should be swapped to create the puzzle.
  swap: [string, string];
}

const toTiles = (equation: string): Tile[] => {
    const parts = equation.split(' ');
    const tiles: Tile[] = [];

    for (const part of parts) {
        if (['+', '-', '*', '/', '=', '_'].includes(part)) {
            tiles.push({ value: part, isLocked: ['=', '+', '-', '*', '/'].includes(part) && part !== '_' });
        } else {
            // Handle multi-digit numbers by splitting them into individual digit tiles
            for (const char of part) {
                if (char === '_') {
                    tiles.push({ value: '_', isLocked: false });
                } else if (!isNaN(parseInt(char, 10))) {
                    tiles.push({ value: parseInt(char, 10), isLocked: false });
                }
            }
        }
    }
    return tiles;
};

// Generates the initial scrambled board state from a correct equation and a swap pair.
const createScrambledBoard = (correctEquation: string, swapPair: [string, string]): Tile[] => {
    let boardStr = correctEquation;
    // To create the puzzle, we perform the swap on the string representation.
    // This is tricky because a value might appear multiple times. We need to swap the FIRST instance.
    const [val1, val2] = swapPair;
    
    // This regex-based approach is safer for multi-character values (like '10')
    const regex1 = new RegExp(`\\b${val1}\\b`);
    const regex2 = new RegExp(`\\b${val2}\\b`);

    const tempPlaceholder = '___TEMP___';
    
    // Check if both values exist before attempting a swap
    if (regex1.test(boardStr) && regex2.test(boardStr)) {
        boardStr = boardStr.replace(regex1, tempPlaceholder);
        boardStr = boardStr.replace(regex2, val1);
        boardStr = boardStr.replace(tempPlaceholder, val2);
    } else {
        console.warn(`Could not perform swap for [${val1}, ${val2}] in equation "${correctEquation}". One or both values not found.`);
    }
    
    return toTiles(boardStr);
};


// This function now correctly finds the indices of the swapped items on the SCRAMBLED board.
const findSwapIndices = (scrambledBoard: Tile[], correctBoard: Tile[]): [number, number] => {
    const diffIndices: number[] = [];
    for (let i = 0; i < scrambledBoard.length; i++) {
        if (scrambledBoard[i].value !== correctBoard[i].value) {
            diffIndices.push(i);
        }
    }

    if (diffIndices.length === 2) {
        return [diffIndices[0], diffIndices[1]];
    }

    // Fallback for safety, though this should not be reached with correct templates.
    console.error("Failed to find exactly two differing indices between scrambled and correct boards.", {
        scrambled: scrambledBoard.map(t => t.value),
        correct: correctBoard.map(t => t.value)
    });
    // Find any two non-locked tiles as a desperate fallback.
    const unlocked = scrambledBoard
        .map((t, i) => ({ t, i }))
        .filter(item => !item.t.isLocked)
        .map(item => item.i);
    
    return [unlocked[0] ?? 0, unlocked[1] ?? 1];
};


const getCorrectSolution = (correctEquation: string): TileValue[] => {
    const solutionTiles = toTiles(correctEquation);
    return solutionTiles.map(tile => tile.value);
};


